"""The animation guide shows real, current movies generated by its printed code."""

from __future__ import annotations

import hashlib
import json
import shutil
import subprocess
import sys
from html.parser import HTMLParser
from pathlib import Path

import numpy as np
import pytest
from _video import probe_video

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "docs/_tooling"))
import make_animation_showcase as showcase  # noqa: E402


class _Players(HTMLParser):
    def __init__(self):
        super().__init__()
        self.videos = []
        self.sources = []

    def handle_starttag(self, tag, attrs):
        if tag == "video":
            self.videos.append(dict(attrs))
        if tag == "source":
            self.sources.append(dict(attrs))


def test_all_nine_examples_have_accessible_lazy_user_controlled_players():
    parser = _Players()
    parser.feed(showcase.PAGE.read_text())
    assert len(parser.videos) == len(parser.sources) == len(showcase.CLIPS) == 9
    for clip, player, source in zip(showcase.CLIPS, parser.videos, parser.sources, strict=True):
        assert "controls" in player and "playsinline" in player
        assert "autoplay" not in player and "loop" not in player
        assert player["preload"] == "none"
        assert (int(player["width"]), int(player["height"])) == clip.pixels
        assert player["aria-label"]
        assert player["poster"].endswith(f"/{clip.slug}-poster.png")
        assert source["src"].endswith(f"/{clip.slug}.mp4")
        assert source["type"] == "video/mp4"


def test_checked_in_movies_match_the_exact_executable_source():
    assert showcase.validate_assets() == []
    records = json.loads(showcase.MANIFEST.read_text())["clips"]
    assert set(records) == {clip.slug for clip in showcase.CLIPS}
    for clip in showcase.CLIPS:
        assert (
            records[clip.slug]["source_sha256"]
            == hashlib.sha256(showcase.example_source(clip.slug).encode()).hexdigest()
        )


def test_caption_edits_do_not_invalidate_footage_but_code_edits_do(tmp_path, monkeypatch):
    page = tmp_path / "animation.md"
    original = showcase.PAGE.read_text()
    page.write_text(original + "\nA prose-only editorial improvement.\n")
    monkeypatch.setattr(showcase, "PAGE", page)
    assert showcase.validate_assets() == []
    page.write_text(page.read_text().replace("duration=10, fps=24", "duration=11, fps=24", 1))
    errors = showcase.validate_assets()
    assert errors and "animation-reveal" in errors[0]
    assert showcase.REGENERATE in errors[0]


@pytest.mark.parametrize("content", ["{}", '{"clips": []}', '{"clips": {}}', "not json"])
def test_malformed_or_incomplete_manifests_fail_with_a_regeneration_command(
    content, tmp_path, monkeypatch
):
    manifest = tmp_path / "manifest.json"
    manifest.write_text(content)
    monkeypatch.setattr(showcase, "MANIFEST", manifest)
    errors = showcase.validate_assets()
    assert errors and showcase.REGENERATE in errors[0]


def test_asset_guard_imports_without_library_or_video_dependencies():
    script = r"""
import importlib.abc
import sys
class NoOptionalLibraries(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname.split('.')[0] in {'matplotlib', 'plotly', 'tsdynamics', 'numpy'}:
            raise ModuleNotFoundError(fullname)
sys.meta_path.insert(0, NoOptionalLibraries())
sys.path.insert(0, 'docs/_tooling')
import make_animation_showcase
assert make_animation_showcase.validate_assets() == []
"""
    subprocess.run([sys.executable, "-c", script], cwd=showcase.ROOT, check=True, timeout=15)


def test_renderer_digest_tracks_drawing_semantics_not_prose_or_installation_path(
    tmp_path, monkeypatch
):
    checkout = tmp_path / "checkout.py"
    wheel = tmp_path / "wheel.py"
    checkout.write_text('__version__ = "1.0"\ndef draw():\n    """Old prose."""\n    return 1\n')
    wheel.write_text(
        '# A new comment\n__version__ = "2.0"\ndef draw():\n    """New prose."""\n    return 1\n'
    )
    monkeypatch.setattr(
        showcase, "_renderer_sources", lambda: [("viz/render/mpl/core.py", checkout)]
    )
    original = showcase.renderer_fingerprint()
    monkeypatch.setattr(showcase, "_renderer_sources", lambda: [("viz/render/mpl/core.py", wheel)])
    assert showcase.renderer_fingerprint() == original
    wheel.write_text("def draw():\n    return 2\n")
    assert showcase.renderer_fingerprint() != original


@pytest.mark.parametrize(
    "field, value",
    [("width", 12), ("renderer_sha256", "old"), ("encoding", {}), ("video", "wrong.mp4")],
)
def test_an_old_renderer_or_changed_export_geometry_invalidates_only_its_record(
    field, value, tmp_path, monkeypatch
):
    manifest = tmp_path / "manifest.json"
    records = json.loads(showcase.MANIFEST.read_text())
    records["clips"]["animation-camera"][field] = value
    manifest.write_text(json.dumps(records))
    monkeypatch.setattr(showcase, "MANIFEST", manifest)
    errors = showcase.validate_assets()
    assert errors and "animation-camera" in errors[0]
    assert "animation-linked:" not in errors[0]
    assert showcase.REGENERATE in errors[0]


@pytest.mark.parametrize("clip", showcase.CLIPS, ids=lambda clip: clip.slug)
def test_each_recipe_executes_without_a_preseeded_namespace(clip):
    assert max(map(len, showcase.example_source(clip.slug).splitlines())) <= 88
    movie = showcase.build_movie(clip.slug)
    assert movie.is_animated
    assert movie.animation.fps == 24
    assert movie.animation.duration in {5, 10, 12} or movie.animation.n_frames == 240


def test_camera_comparison_really_contains_three_independent_signed_views():
    pytest.importorskip("matplotlib")
    import matplotlib.pyplot as plt

    plot = showcase.build_movie("animation-camera")
    movie = plot.render("matplotlib")
    try:
        movie._fig.canvas.draw()
        assert len(movie._fig.axes) == 3
        last = len(list(movie.new_frame_seq())) - 1
        for frame, angles in ((0, [-60, -60, -60]), (last, [-150, -60, 30]), (0, [-60, -60, -60])):
            movie._func(frame)
            assert [axis.azim for axis in movie._fig.axes] == pytest.approx(angles)
            assert [axis.elev for axis in movie._fig.axes] == [24, 24, 24]
    finally:
        plt.close(movie._fig)


def test_map_recipe_preserves_actual_order_and_uses_points():
    import tsdynamics as ts
    from tsdynamics.viz.spec import PlotKind

    movie = showcase.build_movie("animation-map")
    expected = ts.systems.Henon(ic=[0, 0]).run(steps=600)
    assert movie.layers[0].kind == PlotKind.SCATTER
    np.testing.assert_array_equal(movie.layers[0].data["x"], expected.y[:, 0])
    np.testing.assert_array_equal(movie.layers[0].data["y"], expected.y[:, 1])
    assert movie.animation.clock_format == "n = {t:.0f} · frame {i}"
    assert movie.animation.head is False


def test_field_recipe_contains_real_evolving_spatial_snapshots():
    movie = showcase.build_movie("animation-field")
    frames = np.asarray(movie.layers[0].data["frames"])
    assert frames.shape == (241, 48, 48)
    assert np.isfinite(frames).all()
    assert not np.allclose(frames[0], frames[-1])
    assert movie.colorbar.label == "v"


@pytest.mark.parametrize("clip", showcase.CLIPS, ids=lambda clip: clip.slug)
def test_committed_video_decodes_to_the_documented_format_and_has_visible_motion(clip):
    if shutil.which("ffmpeg") is None:
        pytest.skip("requires the optional FFmpeg executable")
    record = json.loads(showcase.MANIFEST.read_text())["clips"][clip.slug]
    movie = showcase.OUT / record["video"]
    info = probe_video(movie)
    assert info.codec_name == "h264" and info.pix_fmt == "yuv420p"
    assert (info.width, info.height) == clip.pixels
    assert info.frame_rate == record["fps"] == 24
    assert info.n_frames == record["frames"]
    assert info.n_frames / info.frame_rate == pytest.approx(record["duration_seconds"])
    assert 8 <= info.n_frames / info.frame_rate <= 12
    assert movie.stat().st_size < 8_000_000
    selected = [round((info.n_frames - 1) * fraction) for fraction in (0.2, 0.6, 0.85)]
    selector = "+".join(f"eq(n\\,{frame})" for frame in selected)
    pixels = subprocess.run(
        [
            "ffmpeg",
            "-v",
            "error",
            "-i",
            str(movie),
            "-vf",
            f"select={selector},scale=160:100",
            "-fps_mode",
            "passthrough",
            "-pix_fmt",
            "rgb24",
            "-f",
            "rawvideo",
            "pipe:1",
        ],
        capture_output=True,
        check=True,
        timeout=30,
    ).stdout
    frames = np.frombuffer(pixels, dtype=np.uint8).reshape(3, 100, 160, 3).astype(float)
    # Ignore outer padding, labels and the top-left clock. Changing clock text
    # alone is not evidence that the plotted orbit/field actually moves.
    plot_area = frames[:, 35:80, 35:145]
    for before, after in zip(plot_area[:-1], plot_area[1:], strict=True):
        changed = np.max(np.abs(after - before), axis=-1) > 12
        assert np.count_nonzero(changed) >= 50
